function classifyByDeviceType(devices) {
    return devices.reduce((accumulator, device) => {
        // 确保累加器中有对应的deviceType键
        if (!accumulator[device.deviceType]) {
            accumulator[device.deviceType] = [];
        }
        // 将当前设备push到对应的deviceType数组中
        accumulator[device.deviceType].push(device);
        return accumulator;
    }, {}); // 初始化累加器为一个空对象
}

