function addDeviceTypeNum(classifiedDevices) {
    for (const deviceType in classifiedDevices) {
        if (classifiedDevices.hasOwnProperty(deviceType)) {
            const devicesArray = classifiedDevices[deviceType];
            devicesArray.forEach((device, index) => {
                device.deviceTypeNum = index+1; // 为每个设备添加deviceTypeNum属性，从0开始递增
            });
        }
    }
    return classifiedDevices;
}

