function addDeviceTypeName(data) {
    // 遍历json数据中的每个对象
    for (const category in data) {
        if (data.hasOwnProperty(category)) {
            const categoryItems = data[category];
            // 遍历每个类别的项
            for (let i = 0; i < categoryItems.length; i++) {
                // 给每个项添加deviceTypeName属性
                categoryItems[i].deviceTypeName = categoryItems[i].deviceType + categoryItems[i].deviceTypeNum;
            }
        }
    }
    return data;
}

