function replaceNameWithValue(arr,str) {
    return arr.map(item => {
        if (Array.isArray(item)) {
            return item.map(subItem => {
                if (typeof subItem === 'object' && subItem !== null && str in subItem) {
                    return subItem[str];
                }
                return subItem;
            });
        } else if (typeof item === 'object' && item !== null && str in item) {
            return item[str];
        }
        return item;
    });
}


