function transformToOnlyDeviceId(arr) {
    return arr.map(subArr => {
        // 检查子数组是否包含对象元素
        if (subArr.some(item => typeof item === 'object' && item !== null)) {
            // 使用map方法转换子数组中的对象元素
            return subArr.map(item => {
                if (typeof item === 'object' && item !== null && item.deviceId) {
                    return { deviceId: item.deviceId };
                }
                // 如果元素不是对象，保持不变
                return item;
            });
        }
        // 如果子数组不包含对象元素，保持不变
        return subArr;
    });
}



