function transformArrayToObject(array, keys) {
  return array.reduce((acc, item) => {
    let current = acc;
    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      const value = item[key];
      if (!current[value]) {
        current[value] = {};
      }
      current = current[value];
    }
    // Assign the value of the last key to the current object
    current[item[keys[keys.length - 1]]] = null; // Using true as a placeholder value
    return acc;
  }, {}); // Start with an empty accumulator object
}
