function extractNumbersByString(array, searchString) {
    const regex = new RegExp(`^${searchString}(\\d+)$`); // 匹配给定字符串的编号的正则表达式

    const numbers = array.filter(item => regex.test(item))
        .map(item => item.match(regex)[1]);

    return numbers;
}
