//两个数组进行加减计算
function calculateArray(operation, arr1, arr2) {
    if (arr1.length !== arr2.length) {
        throw new Error('数组长度不一致');
    }

    if (operation === '+') {
        return arr1.map((item, index) => item + arr2[index]);
    } else if (operation === '-') {
        return arr1.map((item, index) => item - arr2[index]);
    } else {
        throw new Error('无效的操作');
    }
}

