function limitObjectValues(obj, minValue, maxValue) {
    // 遍历对象的每个属性
    for (let key in obj) {
        // 如果属性值小于最小值，就将它设置为最小值
        if (obj[key] < minValue) {
            obj[key] = minValue;
        }
        // 如果属性值大于最大值，就将它设置为最大值
        else if (obj[key] > maxValue) {
            obj[key] = maxValue;
        }
    }
    return obj;
}



