//提取obj中元素key为字符串A+数字+字符串B的元素，并将其重构为新的obj
function extractElements(obj, prefixA, prefixB) {
    const result = {};
    const regex = new RegExp(`${prefixA}\\d+${prefixB}`);

    for (const key in obj) {
        if (obj.hasOwnProperty(key)) {
            if (regex.test(key)) {
                result[key] = obj[key];
            }
        }
    }

    return result;
}

