function assignToGlobalNestedObject(targetObjectName, sourceObject, path, templateObject) {
    const targetObject = global.get(targetObjectName) || {};
    if (path === '') {
        Object.assign(targetObject, sourceObject);
    } else {
        const keys = path.split('.');
        let current = targetObject;
        for (let key of keys) {
            if (!current[key]) current[key] = {}; // If the key doesn't exist, create an empty object
            current = current[key]; // Move to the next nested object
        }
        // Merge if the target is an object and the source is also an object, otherwise assign directly
      //Object.assign(current, sourceObject);

      //初始化  
      Object.assign(templateObject, current);
      Object.assign(templateObject, sourceObject);
      Object.assign(current, templateObject);
    }
  global.set(targetObjectName, targetObject);
  return templateObject;
}


