function subtractObjects(obj1, obj2) {
    const keys = Object.keys(obj1).concat(Object.keys(obj2));
    const result = keys.reduce((acc, key) => {
        const val1 = obj1[key];
        const val2 = obj2[key];

        // 确保两个对象都有这个键
        if (val1 !== undefined && val2 !== undefined) {
            // 进行减法操作
            const difference = val1 - val2;

            // 只有当差值不是null时，才添加到结果中
            if (difference !== null) {
                acc[key] = difference;
            }
        }

        return acc;
    }, {});

    return result;
}

