//映射
function mapValues(obj) {
    return Object.entries(obj).reduce((acc, [key, value]) => {
        if (value > 0.5) {
            acc[key] = 5;
        } else if (value > 0.3) {
            acc[key] = 2;
        } else if (value > 0.1) {
            acc[key] = 1;
        } else if (value > -0.1) {
            acc[key] = 0;
        } else if (value > -0.3) {
            acc[key] = -1;
        } else if (value > -0.5) {
            acc[key] = -2;
        } else if (value <= -0.5) {
            acc[key] = -5;
        }
        return acc;
    }, {});
}

//两个obj相加
function addObjects(obj1, obj2) {
  const result = {};
  // 遍历第一个对象的键
  for (const key in obj1) {
    if (obj1.hasOwnProperty(key)) {
      // 如果第二个对象也有这个键，则相加
      if (obj2.hasOwnProperty(key)) {
        result[key] = obj1[key] + obj2[key];
      } else {
        // 否则直接添加第一个对象的值
        result[key] = obj1[key];
      }
    }
  }
  // 遍历第二个对象的键，确保所有键都被处理
  for (const key in obj2) {
    if (obj2.hasOwnProperty(key) && !result.hasOwnProperty(key)) {
      // 如果结果对象中没有这个键，则添加第二个对象的值
      result[key] = obj2[key];
    }
  }
  return result;
}

//控制权限筛选可控阀门
function cleanObjectByCondition(obj1, obj2) {
  // 遍历obj1对象
  for (let key in obj1) {
    // 检查obj2对象中是否有对应的key，并且其值为false
    if (obj2[key] === false) {
      // 如果条件满足，从obj1中删除该key
      delete obj1[key];
    }
  }
  // 返回处理后的obj1对象
  return obj1;
}

