//对数组求平均
function calculateAverage(array) {
    var sum = 0;
    var count = 0;

    for (var i = 0; i < array.length; i++) {
        if (typeof array[i] === 'number' && !isNaN(array[i])) {
            sum += array[i];
            count++;
        }
    }

    if (count === 0) {
        return null;  // 如果数组中没有有效值，则返回null
    } else {
        return sum / count;  // 返回平均值
    }
}

