function overrideToGlobalNestedObject(targetObjectName, sourceObject, path) {
    const targetObject = global.get(targetObjectName) || {};
    if (path === '') {
        // 如果路径是空字符串，直接assign给目标object
        Object.assign(targetObject, sourceObject);
    } else {
        // 将路径分割成数组
        const keys = path.split('.');
        // 遍历路径的每个部分
        let current = targetObject;
        for (let key of keys) {
            // 如果是最后一个键，赋值sourceObject
            if (key === keys[keys.length - 1]) {
                current[key] = sourceObject;
            } else {
                // 如果中间的键不存在，创建空对象
                current[key] = current[key] || {};
                // 移动到下一个嵌套对象
                current = current[key];
            }
        }
    }
    global.set(targetObjectName, targetObject);
    return targetObject;
}

