function findObjectWithKey(obj, searchString) {
    let result = [];

    function searchObject(obj, path) {
        if (typeof obj === 'object') {
            for (let key in obj) {
                if (typeof obj[key] === 'object') {
                    searchObject(obj[key], path + '.' + key);
                } else {
                    if (key.includes(searchString)) {
                        result.push(path);
                        break;
                    }
                }
            }
        }
    }

    searchObject(obj, '');

    return result.map(name => name.substring(1));
}

