function extractAndRecombine(obj, A, B) {
    const regex = new RegExp(`${A}(\\d+)${B}`);
    const resultObj = {};

    Object.keys(obj).forEach((key) => {
        const match = regex.exec(key);
        if (match) {
            const num = match[1]; // 提取num部分
            const value = obj[key]; // 获取对应的value
            const newKey = `${A}${num}${B}`; // 重组新的key
            resultObj[newKey] = value; // 将新的key和value添加到resultObj
        }
    });

    return resultObj;
}


