//依次提取各编号冷水机组的最小电流百分比
function extractMachineGroupPercentages(data) {
  const machineGroupRegex = /反馈_冷水机组(\d+)压缩机(\d+)电流百分比/; // 正则表达式匹配冷水机组名称和压缩机编号
  const machineGroupPercentages = {}; // 存储提取出的机组百分比

  for (const key in data) {
    const matches = key.match(machineGroupRegex);
    if (matches && matches.length >= 1) {
      const machineGroup = `冷水机组${matches[1]}`;//如果不想要输出的key中<冷水机组>这几个字，就在这里把它删除
      const percentage = data[key];

      if (!machineGroupPercentages[machineGroup]) {
        machineGroupPercentages[machineGroup] = [];
      }
      machineGroupPercentages[machineGroup].push(percentage);
    }
  }

  const machineGroupAverages = {}; // 存储每个机组的平均百分比
  for (const machineGroup in machineGroupPercentages) {
    const percentages = machineGroupPercentages[machineGroup];
    const average = percentages.reduce((sum, percentage) => sum + percentage, 0) / percentages.length;
    machineGroupAverages[machineGroup] = average;
  }

  return machineGroupAverages;
}

